/**
 * 解析当前的目标资源。
 *
 * <p>新的“注入器”玩法：直接注入到资源槽的物品即为目标资源，
 * 256k 元件可以是空的，不再要求资源预先存在元件里。若元件里本身有内容，
 * 则回退到旧的“以元件内数量最多的资源为目标”路径，从而保留流体 / 化学品支持。
 * 二者同时存在但不是同一种资源时视为无效（不会开始合成）。
 */
@Nullable
private AEKey resolveTarget() {
    AEKey cellKey = resolveStoredKey();
    ItemStack resource = inventory.getStackInSlot(SLOT_RESOURCE);
    if (resource.isEmpty()) {
        return cellKey;
    }
    AEItemKey itemKey = AEItemKey.of(resource);
    if (itemKey == null) {
        return null;
    }
    if (cellKey != null && !cellKey.equals(itemKey)) {
        return null;
    }
    return itemKey;
}

/**
 * 资源槽的输入锁定：一旦槽内已有物品，或已锁定目标资源，
 * 就只接受与目标完全相同的物品，避免混入指定以外的资源。
 */
private boolean acceptsIntoResourceSlot(ItemStack stack) {
    if (stack.isEmpty()) {
        return false;
    }
    ItemStack existing = inventory.getStackInSlot(SLOT_RESOURCE);
    if (!existing.isEmpty() && !ItemStack.isSameItemSameTags(existing, stack)) {
        return false;
    }
    AEKey locked = craftingKey != null ? craftingKey : resolveStoredKey();
    if (locked != null) {
        AEItemKey itemKey = AEItemKey.of(stack);
        return itemKey != null && itemKey.equals(locked);
    }
    return true;
}

